      if (tone === "ask" || tone === "approve") return "var(--q)";
      if (tone === "plan") return "var(--accent)";
      if (tone === "fail") return "var(--hi)";
      if (tone === "work" || tone === "wait") return "var(--done)";
      if (tone === "ok") return "var(--soft)";
